window.DV_TOPICS=window.DV_TOPICS||{};window.DV_TOPICS["remote-work"]={"id":"remote-work","order":5,"title_en":"Remote Work Share","title_zh":"远程办公占比","blurb_zh":"办公室、混合与远程的此消彼长","scene_zh":"一份城市白领就业样本（模拟数据）","views":[{"id":"split","type":"stacked","label_zh":"办公方式","label_en":"Work mode","subject":"Where office workers do their jobs","subtitle_en":"Share of employed adults by work mode, 2019 to 2026.","unit":{"en":"percent","short":"%","decimals":0,"kind":"percent","points":true},"data":{"x":{"label_en":"Year","label_zh":"年份","values":["2019","2020","2021","2022","2023","2024","2025","2026"]},"series":[{"id":"office","name_en":"Office","name_zh":"办公室","slot":1,"values":[92,25,40,48,52,55,57,58]},{"id":"hybrid","name_en":"Hybrid","name_zh":"混合","slot":2,"values":[6,30,35,32,30,29,28,28]},{"id":"remote","name_en":"Remote","name_zh":"远程","slot":3,"values":[2,45,25,20,18,16,15,14]}],"mode":"percent"},"features":[{"kind":"composition","marks":["stack:0"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2019","period":"2019","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"share_shift","marks":["seg:0:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2019","period":"2019","series_name":"Office","value":"92 percent","share":"92 percent","share_number":"92","total":"100 percent"},"auto":false,"id":"rw-collapse","examples":[{"en":"Office work collapsed from 92 percent in 2019 to 25 percent in 2020.","zh":"办公室办公从 2019 年的 92% 跌到 2020 年的 25%。"}],"note_zh":"collapse 比 fall 更强调骤降，适合一年内掉 67 个百分点这种幅度。","interpret_zh":"这是办公方式结构的重排，不等于就业人数减少。"},{"kind":"component_growth","marks":["seg:0:hybrid","seg:1:hybrid"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2019","period":"2019","series_name":"Hybrid","value":"6 percent","share":"6 percent","share_number":"6","total":"100 percent"},"auto":false,"id":"rw-hybrid-rise","examples":[{"en":"Hybrid work grew from 6 percent in 2019 to 30 percent in 2020.","zh":"混合办公从 2019 年的 6% 增长到 2020 年的 30%。"}],"note_zh":"grow from ... to ... 同时给出起点和终点，比只说 grew 清楚。","interpret_zh":"混合办公的涨幅很大，但起点只有 6%，百分比增幅不宜直接外推。"},{"kind":"item","marks":["seg:0:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2019","period":"2019","series_name":"Remote","value":"2 percent","share":"2 percent","share_number":"2","total":"100 percent"},"auto":true},{"kind":"composition","marks":["stack:1"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2020","period":"2020","value":"100 percent","share":"100 percent"},"auto":false,"id":"rw-composition","examples":[{"en":"In 2020, the workforce split into 25 percent office, 30 percent hybrid and 45 percent remote.","zh":"2020 年，就业人群分成 25% 办公室、30% 混合和 45% 远程。"}],"note_zh":"split into + 各部分，适合描述一整根堆叠柱。","interpret_zh":"三项加起来是 100%，说明这张图只比较结构，不比较总人数。"},{"kind":"item","marks":["seg:1:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2020","period":"2020","series_name":"Office","value":"25 percent","share":"25 percent","share_number":"25","total":"100 percent"},"auto":true},{"kind":"largest_component","marks":["seg:1:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2020","period":"2020","series_name":"Remote","value":"45 percent","share":"45 percent","share_number":"45","total":"100 percent"},"auto":false,"id":"rw-remote-peak","examples":[{"en":"Remote work was the largest single mode in 2020, at 45 percent.","zh":"2020 年远程办公是最大的单一方式，占 45%。"}],"note_zh":"the largest single mode 强调单项第一，避免和总量混淆。","interpret_zh":"远程办公只在 2020 年超过办公室，之后没有再次反超。"},{"kind":"composition","marks":["stack:2"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2021","period":"2021","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"largest_component","marks":["seg:2:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2021","period":"2021","series_name":"Office","value":"40 percent","share":"40 percent","share_number":"40","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:2:hybrid"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2021","period":"2021","series_name":"Hybrid","value":"35 percent","share":"35 percent","share_number":"35","total":"100 percent"},"auto":true},{"kind":"share_shift","marks":["seg:2:remote","seg:7:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2021","period":"2021","series_name":"Remote","value":"25 percent","share":"25 percent","share_number":"25","total":"100 percent"},"auto":false,"id":"rw-remote-fall","examples":[{"en":"Remote work kept shrinking after 2021, from 25 percent to 14 percent in 2026.","zh":"远程办公在 2021 年后持续收缩，从 25% 降到 2026 年的 14%。"}],"note_zh":"keep + 动词-ing 表示持续；shrink 强调份额变小。","interpret_zh":"远程办公的绝对人数可能没变，下降的是它在样本中的占比。"},{"kind":"composition","marks":["stack:3"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2022","period":"2022","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"largest_component","marks":["seg:3:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2022","period":"2022","series_name":"Office","value":"48 percent","share":"48 percent","share_number":"48","total":"100 percent"},"auto":true},{"kind":"dominant_trend","marks":["seg:3:hybrid","seg:7:hybrid"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2022","period":"2022","series_name":"Hybrid","value":"32 percent","share":"32 percent","share_number":"32","total":"100 percent"},"auto":false,"id":"rw-hybrid-steady","examples":[{"en":"Hybrid work has stayed in a narrow band, between 28 and 32 percent, since 2022.","zh":"混合办公自 2022 年以来一直停留在 28% 到 32% 的窄区间。"}],"note_zh":"stay in a narrow band 比 stay the same 更具体。","interpret_zh":"稳定的是占比，不是每家公司内部的安排。"},{"kind":"item","marks":["seg:3:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2022","period":"2022","series_name":"Remote","value":"20 percent","share":"20 percent","share_number":"20","total":"100 percent"},"auto":true},{"kind":"composition","marks":["stack:4"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2023","period":"2023","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"largest_component","marks":["seg:4:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2023","period":"2023","series_name":"Office","value":"52 percent","share":"52 percent","share_number":"52","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:4:hybrid"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2023","period":"2023","series_name":"Hybrid","value":"30 percent","share":"30 percent","share_number":"30","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:4:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2023","period":"2023","series_name":"Remote","value":"18 percent","share":"18 percent","share_number":"18","total":"100 percent"},"auto":true},{"kind":"composition","marks":["stack:5"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2024","period":"2024","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"largest_component","marks":["seg:5:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2024","period":"2024","series_name":"Office","value":"55 percent","share":"55 percent","share_number":"55","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:5:hybrid"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2024","period":"2024","series_name":"Hybrid","value":"29 percent","share":"29 percent","share_number":"29","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:5:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2024","period":"2024","series_name":"Remote","value":"16 percent","share":"16 percent","share_number":"16","total":"100 percent"},"auto":true},{"kind":"composition","marks":["stack:6"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2025","period":"2025","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"largest_component","marks":["seg:6:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2025","period":"2025","series_name":"Office","value":"57 percent","share":"57 percent","share_number":"57","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:6:hybrid"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2025","period":"2025","series_name":"Hybrid","value":"28 percent","share":"28 percent","share_number":"28","total":"100 percent"},"auto":true},{"kind":"item","marks":["seg:6:remote"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2025","period":"2025","series_name":"Remote","value":"15 percent","share":"15 percent","share_number":"15","total":"100 percent"},"auto":true},{"kind":"composition","marks":["stack:7"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2026","period":"2026","value":"100 percent","share":"100 percent"},"auto":true},{"kind":"component_growth","marks":["seg:7:office"],"slots":{"subject":"Where office workers do their jobs","unit":"%","category":"2026","period":"2026","series_name":"Office","value":"58 percent","share":"58 percent","share_number":"58","total":"100 percent"},"auto":false,"id":"rw-office-back","examples":[{"en":"Office work recovered to 58 percent by 2026, still below its 2019 level.","zh":"办公室办公到 2026 年回升到 58%，仍低于 2019 年的水平。"}],"note_zh":"recover to + 结果；still below 补一句对比，避免只说回升。","interpret_zh":"回升不等于回到原点：58% 比 2019 年的 92% 低 34 个百分点。"}],"overview_zh":"远程办公在 2020 年冲到 45%，随后逐年回落；办公室工作从 25% 回升到 58%，混合办公稳定在 28% 上下。三种方式每年合计都是 100%，看的是结构变化，不是就业人数。","descriptions":{"general":{"a2":"In 2019, almost everyone worked in an office. By 2020, office work fell to 25 percent, and remote work rose to 45 percent. Since then, more people have gone back to the office, and remote work has slowly fallen to 14 percent in 2026.","b1":"Office work dropped from 92 percent in 2019 to 25 percent in 2020, while remote work jumped from 2 to 45 percent. The pattern then reversed: office work recovered to 58 percent by 2026, and hybrid work settled at around 28 percent.","b2":"The shift was abrupt. Office work fell 67 percentage points in a single year, to 25 percent, before recovering steadily to 58 percent in 2026. Hybrid work expanded from 6 to 30 percent and has held near 28 percent since 2022, while remote-only work has declined every year since its 2020 peak of 45 percent."},"ielts":"Office work accounted for 92 percent of workers in 2019 but fell to 25 percent in 2020, when remote work peaked at 45 percent. By 2026, office work had recovered to 58 percent, hybrid work stood at 28 percent, and remote work had fallen to 14 percent.","business":"The 2020 shift pushed remote work from 2 to 45 percent in a single year, but the reversal was just as fast. Office work is back to 58 percent, hybrid has settled near 28 percent, and remote-only work keeps shrinking; the stable hybrid band is where policy should focus."}},{"id":"by-sector","type":"bar","label_zh":"行业差异","label_en":"By sector","subject":"Hybrid or remote work by sector","subtitle_en":"Share of workers with hybrid or remote arrangements in 2026.","unit":{"en":"percent","short":"%","decimals":0,"kind":"percent","points":true},"data":{"x":{"label_en":"Sector","label_zh":"行业","values":["Tech","Finance","Media","Education","Manufacturing","Retail"]},"series":[{"id":"flex","name_en":"Hybrid or remote","name_zh":"混合或远程","slot":1,"values":[46,38,35,22,14,8]}]},"features":[{"kind":"highest","marks":["bar:flex:0"],"slots":{"subject":"Hybrid or remote work by sector","unit":"%","category":"Tech","period":"","series_name":"Hybrid or remote","value":"46 percent","rank":"1","gap":"0 percentage points","top_category":"Tech","top_value":"46 percent"},"auto":false,"id":"rw-sector-tech","examples":[{"en":"Tech has the highest share, at 46 percent.","zh":"科技行业的比例最高，为 46%。"}],"note_zh":"the highest share / the highest figure + at + 数值。","interpret_zh":"行业差异只说明 2026 年的截面，不说明过去几年怎么变。"},{"kind":"ranking","marks":["bar:flex:1"],"slots":{"subject":"Hybrid or remote work by sector","unit":"%","category":"Finance","period":"","series_name":"Hybrid or remote","value":"38 percent","rank":"2","gap":"8 percentage points","top_category":"Tech","top_value":"46 percent"},"auto":false,"id":"rw-sector-finance","examples":[{"en":"Finance ranks second, at 38 percent.","zh":"金融排第二，为 38%。"}],"note_zh":"rank + 序数词，不加 the；也可以说 comes second。","interpret_zh":"第二名和第一名只差 8 个百分点。"},{"kind":"ranking","marks":["bar:flex:2"],"slots":{"subject":"Hybrid or remote work by sector","unit":"%","category":"Media","period":"","series_name":"Hybrid or remote","value":"35 percent","rank":"3","gap":"11 percentage points","top_category":"Tech","top_value":"46 percent"},"auto":true},{"kind":"compare_groups","marks":["bar:flex:3"],"slots":{"subject":"Hybrid or remote work by sector","unit":"%","category":"Education","period":"","series_name":"Hybrid or remote","value":"22 percent","rank":"4","gap":"24 percentage points","top_category":"Tech","top_value":"46 percent"},"auto":false,"id":"rw-sector-education","examples":[{"en":"Education is at 22 percent, well below Media at 35 percent.","zh":"教育为 22%，明显低于媒体的 35%。"}],"note_zh":"well below 表示差距明显；这里差 13 个百分点，语气偏强但成立。","interpret_zh":"教育的工作内容和场地限制，是这张图看不出来的背景。"},{"kind":"item","marks":["bar:flex:4"],"slots":{"subject":"Hybrid or remote work by sector","unit":"%","category":"Manufacturing","period":"","series_name":"Hybrid or remote","value":"14 percent","rank":"5","gap":"32 percentage points","top_category":"Tech","top_value":"46 percent"},"auto":false,"id":"rw-sector-manufacturing","examples":[{"en":"Manufacturing comes in at 14 percent.","zh":"制造业为 14%。"}],"note_zh":"come in at + 数值，常用于报告结果。","interpret_zh":"14% 不代表制造业没有远程岗位，只是比例低。"},{"kind":"lowest","marks":["bar:flex:5"],"slots":{"subject":"Hybrid or remote work by sector","unit":"%","category":"Retail","period":"","series_name":"Hybrid or remote","value":"8 percent","rank":"6","gap":"38 percentage points","top_category":"Tech","top_value":"46 percent"},"auto":false,"id":"rw-sector-retail","examples":[{"en":"Retail has the lowest share, at 8 percent.","zh":"零售业比例最低，为 8%。"}],"note_zh":"the lowest share / the lowest figure。","interpret_zh":"最低值接近零，描述时不要说 no remote work。"}],"overview_zh":"行业之间差距很大：科技 46% 最高，零售 8% 最低。知识型行业普遍在 35% 以上，制造和零售不到 15%。","descriptions":{"general":{"a2":"Tech is the highest, at 46 percent. Finance follows at 38 percent, and Media at 35 percent. Education is lower, at 22 percent. Manufacturing and Retail have the smallest shares, at 14 and 8 percent.","b1":"Hybrid and remote work is most common in Tech, at 46 percent, followed by Finance at 38 percent and Media at 35 percent. Education stands at 22 percent, while Manufacturing and Retail trail at 14 and 8 percent.","b2":"Flexible work is concentrated in knowledge sectors: Tech, Finance and Media all sit at 35 percent or more, while Education sits at 22 percent. Manufacturing and Retail report just 14 and 8 percent. The gap between Tech and Retail is 38 percentage points, wider than the gap between Tech and Manufacturing."},"ielts":"Tech recorded the highest share of hybrid or remote workers at 46 percent, followed by Finance and Media at 38 and 35 percent respectively. Education stood at 22 percent, and Manufacturing and Retail had the lowest shares at 14 and 8 percent.","business":"Flexible work is a knowledge-sector benefit: Tech, Finance and Media are all at or above 35 percent, while Manufacturing and Retail are under 15. For hiring, the 46 percent Tech figure is the benchmark competitors will be measured against."}}]};
